import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the resolved
     * path and ensuring it stays within {@code dir}. It also strips any query
     * parameters from {@code name} and guarantees that the resulting file
     * does not overwrite existing files by appending a numeric suffix if
     * necessary.
     *
     * @param dir  the target directory where the file should be created
     * @param name the desired file name (may contain path separators)
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IllegalArgumentException if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory cannot be null");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("File name cannot be null or empty");
        }

        // Remove query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the target directory
        Path dirPath = dir.toPath().normalize();
        Path candidatePath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still within the target directory
        if (!candidatePath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempted to create a file outside the target directory: " + name);
        }

        File file = candidatePath.toFile();

        // Determine prefix and suffix for generating a unique filename
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            candidatePath = dirPath.resolve(newName).normalize();
            file = candidatePath.toFile();
        }

        // Create any missing parent directories
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }

        return file;
    }

    // other methods
}
```

