    /**
     * Decodes a JWT string into a {@link JWT} object while performing
     * rigorous validation of the header, signature and claims.
     *
     * @param encodedJWT the compact JWT representation
     * @param header     the decoded header containing the algorithm
     * @param parts      the three Base64URL encoded parts of the JWT
     * @param verifier   the verifier capable of validating the signature
     * @return the decoded {@link JWT}
     */
    private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {

        /* ----------------------------------------------------------------- */
        /*  1. Validate the algorithm declared in the header.                 */
        /* ----------------------------------------------------------------- */
        if (header == null || header.algorithm == null) {
            throw new IllegalArgumentException("JWT header or algorithm cannot be null");
        }

        String algName = header.algorithm.getName();

        // Reject the insecure 'none' algorithm unconditionally.
        if ("none".equalsIgnoreCase(algName)) {
            throw new MissingVerifierException(
                    "Unsigned JWTs are not permitted (algorithm='none')"
            );
        }

        // Enforce a whitelist of supported algorithms.
        if (!ALLOWED_ALGORITHMS.contains(algName)) {
            throw new UnsupportedOperationException(
                    "Unsupported JWT algorithm: " + algName
            );
        }

        /* ----------------------------------------------------------------- */
        /*  2. Verify that the presence of a signature matches expectations. */
        /* ----------------------------------------------------------------- */
        if (parts.length == 3 && verifier == null) {
            throw new MissingVerifierException(
                    "No Verifier has been provided for a signature signed using [" + algName + "]"
            );
        }

        if (parts.length == 2 && verifier != null) {
            throw new InvalidJWTSignatureException();
        }

        /* ----------------------------------------------------------------- */
        /*  3. Prepare the message that was signed (header.payload).          */
        /* ----------------------------------------------------------------- */
        int index = encodedJWT.lastIndexOf(".");
        byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

        /* ----------------------------------------------------------------- */
        /*  4. Verify the signature if one is present.                        */
        /* ----------------------------------------------------------------- */
