public class DefaultURLConstructor implements URLConstructor {

    private static final Logger LOG = Logger.getLogger(DefaultURLConstructor.class.getName());

    // Allowed characters for a JSP page name: letters, digits, underscore, hyphen, dot
    private static final Pattern VALID_PAGE_PATTERN = Pattern.compile("^[A-Za-z0-9_\\-\\.]+$");

    // Fallback page when the requested path is invalid
    private static final String DEFAULT_PAGE = "Default.jsp";

    // other methods

    /**
     * Returns the name of the JSP page to forward to.
     * <p>
     * The method now performs strict validation and sanitisation of the
     * path information obtained from the request. It rejects any path that
     * contains directory traversal sequences or characters outside the
     * allowed set, thereby preventing attackers from accessing arbitrary
     * files on the server.
     *
     * @param request The HTTP request that was used to reach this page.
     * @return A safe JSP page name, or {@code DEFAULT_PAGE} if the input is
     *         invalid or missing.
     */
    @Override
    public String getForwardPage(HttpServletRequest request) {
        String pathInfo = request.getPathInfo();

        // If no path info is supplied, fall back to a default page
        if (pathInfo == null || pathInfo.isEmpty()) {
            return DEFAULT_PAGE;
        }

        // Normalise separators and strip leading slash(es)
        String normalized = pathInfo.replaceAll("[/\\\\]+", "/");
        if (normalized.startsWith("/")) {
            normalized = normalized.substring(1);
        }

        // Reject any path containing directory traversal components
        if (normalized.contains("..") || normalized.startsWith("../") || normalized.endsWith("/..")) {
            LOG.warning("Attempted path traversal detected: " + pathInfo);
            return DEFAULT_PAGE;
        }

        // Validate against a whitelist of allowed characters
        if (!VALID_PAGE_PATTERN.matcher(normalized).matches()) {
            LOG.warning("Invalid characters in path: " + pathInfo);
            return DEFAULT_PAGE;
        }

        // At this point the path is considered safe
        return normalized;
    }

    // other methods
}
