     * Include the specified resource via the RequestDispatcher.
     *
     * @param request     current HTTP request
     * @param response    current HTTP response
     * @param resourceUrl the URL of the target resource
     * @throws ServletException if thrown by the RequestDispatcher
     * @throws IOException      if thrown by the RequestDispatcher
     */
    private void doInclude(HttpServletRequest request, HttpServletResponse response,
                           String resourceUrl) throws ServletException, IOException {
        if (this.contentType != null) {
            response.setContentType(this.contentType);
        }

        if (resourceUrl == null || resourceUrl.trim().isEmpty()) {
            return; // nothing to include
        }

        String[] resourceUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);
        for (String url : resourceUrls) {
            url = url.trim();
            if (url.isEmpty()) {
                continue;
            }

            // Strict path validation to prevent directory traversal
            if (!isPathSafe(url)) {
                throw new ServletException("Attempt to include unsafe resource [" + url + "]");
            }

            if (this.allowedResources != null && !this.pathMatcher.match(this.allowedResources, url)) {
                throw new ServletException("Resource [" + url + "] does not match allowed pattern ["
                        + this.allowedResources + "]");
            }

            if (logger.isDebugEnabled()) {
                logger.debug("Including resource [{}]", url);
            }

            RequestDispatcher rd = request.getRequestDispatcher(url);
            rd.include(request, response);
        }
    }

    /**
     * Determines whether a resource path is safe for inclusion.
     *
     * @param path the resource path to validate
     * @return {@code true} if the path is considered safe, {@code false} otherwise
     */
    private boolean isPathSafe(String path) {
        // Reject null or empty paths
        if (path == null || path.isEmpty()) {
            return false;
        }

        // Reject absolute paths or paths containing backslashes
        if (path.startsWith("/") || path.contains("\\") || path.matches("^[a-zA-Z]:.*")) {
            return false;
        }

        // Reject obvious traversal attempts
        if (path.contains("..") || path.startsWith("./") || path.endsWith("/..")) {
            return false;
        }

        // Normalize the path and ensure it does not escape the context root
        Path normalized = Paths.get(path).normalize();
        if (normalized.startsWith("..")) {
            return false;
        }

        // Additional check: ensure the resolved real path stays within the servlet context
        try {
            String realPath = request.getServletContext().getRealPath(path);
            if (realPath == null) {
                // If the container cannot resolve the path, treat it as unsafe
                return false;
            }
            Path canonical = Paths.get(realPath).toRealPath();
            Path contextRoot = Paths.get(request.getServletContext().getRealPath("/")).toRealPath();
            return canonical.startsWith(contextRoot);
        } catch (Exception e) {
            // Any exception during resolution is treated as unsafe
            return false;
        }
    }

