protected Locale getLocaleFromParam(Object requestedLocale) {
    Locale locale = null;
    if (requestedLocale != null) {
        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();
            if (!localeStr.isEmpty() && isValidLocaleString(localeStr)) {
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
            } else {
                LOG.warn("Invalid locale parameter received: {}", localeStr);
            }
        }
        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }
    }
    return locale;
}

private boolean isValidLocaleString(String localeStr) {
    // pattern: language[-country][-variant] where language 2-3 letters, country 2 letters, variant alphanumeric
    // Accept underscore or hyphen separators
    String[] parts = localeStr.split("[-_]");
    if (parts.length < 1 || parts.length > 3) {
        return false;
    }
    // language
    if (!parts[0].matches("[a-zA-Z]{2,3}")) {
        return false;
    }
    // country optional
    if (parts.length >= 2 && !parts[1].matches("[a-zA-Z]{2}")) {
        return false;
    }
