private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principal,
                                                Object credentials) throws NamingException {
    // Cast to the concrete factory to obtain configuration values
    JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;

    // Environment for an anonymous bind – authentication will be performed after TLS
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());
    env.put(Context.SECURITY_AUTHENTICATION, "none"); // anonymous bind

    LdapContext ctx = null;
    StartTlsResponse tls = null;

    try {
        // Create the context and negotiate STARTTLS
        ctx = new InitialLdapContext(env, null);
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();

        // Bind with the supplied credentials over the secured channel
        ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                jndiLdapContextFactory.getAuthenticationMechanism());
        ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
        ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

        // Force a simple operation to trigger authentication and validate credentials
        ctx.lookup("");

        return ctx;
    } catch (AuthenticationException ae) {
        // Authentication failed – close resources and surface a clear error
        LdapUtils.closeContext(ctx);
        securityLog.warn(withRealm("LDAP authentication failed for principal '%s' on '%s'.",
                principal, server(jndiLdapContextFactory)));
        throw ae;
    } catch (IOException ioe) {
        // TLS negotiation failed
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                server(jndiLdapContextFactory), ioe.getMessage()), ioe);
        throw new CommunicationException(ioe.getMessage());
    } catch (Throwable t) {
        // Unexpected failure – ensure cleanup
        LdapUtils.closeContext(ctx);
        securityLog.error(withRealm("Unexpected failure to establish LDAP connection with '%s': %s",
                server(jndiLdapContextFactory), t.getMessage()), t);
        throw t;
    } finally {
        if (tls != null) {
            try {
                tls.close();
            } catch (IOException ignored) {
                // ignore
            }
        }
    }
}
